// Firebase configuration, per-platform.
//
// Normally generated by `flutterfire configure`. Written by hand here from
// android/app/google-services.json and ios/Runner/GoogleService-Info.plist
// because the flutterfire CLI isn't on PATH. If you add macOS/web later,
// run `flutterfire configure` (or `dart pub global run
// flutterfire_cli:flutterfire configure`) and let it regenerate this file.
//
// These values are not secrets: the Firebase API key is a project
// identifier shipped in every client build, not an auth credential. Access
// is controlled by Firebase Security Rules and (for FCM) the server key.
// ignore_for_file: type=lint
import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show defaultTargetPlatform, kIsWeb, TargetPlatform;

class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      throw UnsupportedError(
        'DefaultFirebaseOptions have not been configured for web - '
        'run flutterfire configure again to add web support.',
      );
    }
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      case TargetPlatform.iOS:
        return ios;
      case TargetPlatform.macOS:
        throw UnsupportedError(
          'DefaultFirebaseOptions have not been configured for macOS - '
          'run `flutterfire configure` after adding the macOS Firebase app.',
        );
      case TargetPlatform.windows:
        throw UnsupportedError(
          'DefaultFirebaseOptions have not been configured for windows - '
          'run flutterfire configure again to add windows support.',
        );
      case TargetPlatform.linux:
        throw UnsupportedError(
          'DefaultFirebaseOptions have not been configured for linux - '
          'run flutterfire configure again to add linux support.',
        );
      default:
        throw UnsupportedError(
          'DefaultFirebaseOptions are not supported for this platform.',
        );
    }
  }

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaSyAtAmRm0gIlAy66uSIXwYyAD8APhG7NF_w',
    appId: '1:866082036026:android:9ba38bbcf9045f1643d803',
    messagingSenderId: '866082036026',
    projectId: 'esmfamil-87855',
    storageBucket: 'esmfamil-87855.firebasestorage.app',
  );

  static const FirebaseOptions ios = FirebaseOptions(
    apiKey: 'AIzaSyCLV7hHIfOAx5_rrNH7jkF3DK-ubMrMIAQ',
    appId: '1:866082036026:ios:a2c424a1c4b21cec43d803',
    messagingSenderId: '866082036026',
    projectId: 'esmfamil-87855',
    storageBucket: 'esmfamil-87855.firebasestorage.app',
    iosBundleId: 'com.PardisSaz.game',
  );
}
